Let~$K$ be a number field such that $\Acal\subset K$. For~$\a\in\Acal$ and~$v\in M_K$, we let \[ \a_v =  egin{cases} \a&	ext{if $\|\a\|_v\le1$,}\ \a^{-1}&	ext{if $\|\a\|_v>1$,}\ \end{cases} \] so in particular $\|\a_v\|_v\le 1$. We now compute  egin{align} (n\log m)\D(\Acal,m,n) &= \sum_{\a\in\Acal}\sum_{v\mid m} v(\a^n-1) &&	ext{def. of $\D(\Acal,m,n)$,} 
otag\ &\le \sum_{\a\in\Acal}\sum_{v\in M_K^0} v(\a^n-1) &&	ext{since $\a\in ar\ZZ$,} 
otag\ &= \sum_{\a\in\Acal}\sum_{v\in M_K^\infty} \log\|\a^n-1\|_v &&	ext{product rule,} 
otag\ &\le \sum_{\a\in\Acal}\sum_{\substack{v\in M_K^\infty\\|\a\|_v>1\}} \log\|\a^n\|_v + \sum_{\a\in\Acal}\sum_{v\in M_K^\infty} \log\|\a_v^n-1\|_v \hidewidth 
otag\ &= n\sum_{\a\in\Acal} h(\a) + \sum_{\a\in\Acal}\sum_{v\in M_K^\infty} \log\|\a_v^n-1\|_v. \hidewidth \end{align} We now replace~$\Acal$ with~$\Acal^j$. Then using $h(\a^j)=jh(\a)$ and Proposition~ef{prop:DAjmngeDAmn}, which says that $\D(\Acal,m,n)\le\D(\Acal^j,m,n)$, we find that \[ (n\log m)\D(\Acal,m,n) \le nj\sum_{\a\in\Acal}h(\a) + \sum_{\a\in\Acal}\sum_{v\in M_K^\infty} \log\|\a_v^{jn}-1\|_v . \] We multiply by the Fej'er multiplier $1- rac{j}{J+1}$ and sum over $1\le j\le J$ to obtain  egin{multline*}  rac{Jn\log m}{2}\D(\Acal,m,n) \le  rac{(J^2+2J)n}{6}\sum_{\a\in\Acal}h(\a) \* + \sum_{\a\in\Acal}\sum_{v\in M_K^\infty} \sum_{j=1}^J \left(1- rac{j}{J+1}ight)\log\|\a_v^{jn}-1\|_v . \end{multline*} Note that the sum over~$v$ is over archimedean absolute values, so if we assume that~$\a_v$ is chosen in the unit disk to maximize the innermost sum over~$j$, we get the estimate  egin{multline*}  rac{Jn\log m}{2}\D(\Acal,m,n) \* \le  rac{(J^2+2J)n}{6}\sum_{\a\in\Acal}h(\a) + |\Acal| \sup_{\substack{z\in\CC\|z|\le1\}} \sum_{j=1}^J \left(1- rac{j}{J+1}ight)\log|z^j-1|. \end{multline*} We can now use Proposition~ef{prop:fejarestimate} to conclude that \[  rac{Jn\log m}{2}\D(\Acal,m,n) \le  rac{(J^2+2J)n}{6}\sum_{\a\in\Acal}h(\a) +  rac{|\Acal|}{2}\left(\log\left( rac{J}{2}+1ight)+1ight). \] After a little bit of algebra, we obtain the desired result.

We now compute  egin{align} (n\log m)\D(\Acal,m,n) &= \sum_{\a\in\Acal}\sum_{v\mid m} v(\a^n-1) &&	ext{def. of $\D(\Acal,m,n)$,} 
otag\ &\le \sum_{\a\in\Acal}\sum_{v\in M_K^0} v(\a^n-1) &&	ext{since $\a\in ar\ZZ$,} 
otag\ &= \sum_{\a\in\Acal}\sum_{v\in M_K^\infty} \log\|\a^n-1\|_v &&	ext{product rule,} 
otag\ &\le \sum_{\a\in\Acal}\sum_{\substack{v\in M_K^\infty\\|\a\|_v>1\}} \log\|\a^n\|_v + \sum_{\a\in\Acal}\sum_{v\in M_K^\infty} \log\|\a_v^n-1\|_v \hidewidth 
otag\ &= n\sum_{\a\in\Acal} h(\a) + \sum_{\a\in\Acal}\sum_{v\in M_K^\infty} \log\|\a_v^n-1\|_v. \hidewidth \end{align}
